 for(const alert of data.monitorAlerts||[])content.prepend(el('div',{class:'notice'},[el('strong',{text:'外链状态发生变化'}),el('p',{text:(data.model.products.find(p=>p.id===alert.profileId)?.name||'我的网站')+' · '+(monitorLabels[alert.status]||'请人工复查')}),...(deliveryLabels[alert.desktopDelivery?.status]?[el('p',{class:'muted',text:deliveryLabels[alert.desktopDelivery.status]})]:[]),el('a',{href:alert.url,target:'_blank',rel:'noreferrer',text:'打开原公开页面'}),button('已查看',async()=>{await request('/dismissMonitorAlert',{id:alert.id});await load();})]));
